using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
using Microsoft.Win32;

namespace DoonPanelPreview {
 public sealed partial class Workbench {
  OrderDraft currentDraft;
  void Orders(){
   Heading("订单核对与金蝶导出","选择订单 → 匹配价格和物料 → 补齐并核对 → 导出金蝶导入包。原件和历史版本保存在本机。");
   var actions=new WrapPanel();content.Children.Add(actions);
   actions.Children.Add(Btn("上传订单 Excel",UploadOrder));actions.Children.Add(Btn("已保存草稿",DraftLibrary));actions.Children.Add(Btn("导出记录",ExportLibrary));actions.Children.Add(Btn("模板设置",TemplateSettings));
   if(currentDraft==null){content.Children.Add(Label("沿用：美元单价 × 7 × 0.89，人民币单价保留 4 位小数；税率 13%；默认交期为今天 +105 天。\n上述参数均可在核对前修改。支持与已提供 PI 兼容的 .xlsx 表头；其他版式会提示缺少字段。\n\n价格库与金蝶清单只读引用，草稿单独保存。不会自动写入金蝶。"));return;}
   var ctx=store.OrderContext();var preview=OrderFlow.Preview(currentDraft,ctx);
   content.Children.Add(Label(currentDraft.File+" · "+preview.Lines.Count+" 行 · 草稿版本 "+currentDraft.Version+" · 待核对 "+preview.Lines.Count(l=>l.Errors.Count>0)+" 行"));
   var s=currentDraft.Settings;content.Children.Add(Btn("修改日期、业务员与换算参数",()=>EditOrderSettings(ctx)));
   content.Children.Add(Label("日期 "+s.BillDate+"  /  交期 "+s.DeliveryDate+"  /  业务员 "+s.Salesperson+"  /  "+s.BusinessType+"\nUSD × "+s.Rate+" × "+s.Factor+" → CNY（4 位）  /  税率 "+s.Tax+"%  /  PCS → "+s.PcsUnit+"（数量不变）\n新建商品默认仓库："+s.Warehouse+"；可为子件、可自制、可销售、可采购：是。"));
   if(preview.Errors.Count>0)content.Children.Add(Label("整单待处理：\n"+string.Join("\n",preview.Errors)));
   var confirm=new CheckBox{Content="我已核对全部明细、价格来源、编码、名称、单位及导出参数",IsChecked=currentDraft.ReviewHash==preview.Fingerprint&&preview.Ready,IsEnabled=preview.Ready,Margin=new Thickness(0,12,0,12)};
   var export=Btn("导出金蝶导入包 (.zip)",()=>{
    var d=new SaveFileDialog{Title="保存金蝶导入包（使用新文件名）",Filter="金蝶导入包 (*.zip)|*.zip",FileName="度昂金蝶导入-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".zip"};if(d.ShowDialog()!=true)return;
    string hash=OrderExporter.Save(store,currentDraft,d.FileName);Detail("导出完成","已生成并回读校验：\n"+d.FileName+"\n\nSHA-256："+hash+"\n\n解压后导入金蝶。如包含商品新建表，须先导入并核验商品，再导入销售订单。金蝶实际导入尚需你在账套内核验。",null);
   });export.IsEnabled=confirm.IsChecked==true;
   confirm.Checked+=(o,e)=>{try{var fresh=OrderFlow.Preview(currentDraft,store.OrderContext());if(!fresh.Ready||fresh.Fingerprint!=preview.Fingerprint)throw new InvalidOperationException("资料已更新，请刷新预览重新核对。");currentDraft.ReviewHash=fresh.Fingerprint;currentDraft.ReviewedBy=PriceStore.Actor;currentDraft.ReviewedAt=DateTime.UtcNow.ToString("o");store.SaveDraft(currentDraft);export.IsEnabled=true;}catch(Exception ex){confirm.IsChecked=false;MessageBox.Show(this,ex.Message,"确认未保存");}};
   confirm.Unchecked+=(o,e)=>{currentDraft.ReviewHash="";currentDraft.ReviewedAt="";currentDraft.ReviewedBy="";export.IsEnabled=false;try{store.SaveDraft(currentDraft);}catch(Exception ex){MessageBox.Show(this,ex.Message,"取消确认未保存");}};content.Children.Add(confirm);content.Children.Add(export);
   content.Children.Add(Label("点击单号或“查看详情”查看完整依据，再单独编辑。本页是字段核对视图；工作簿计算、原版打印请用 Excel 打开原件。\n商品名称按镜架与镜片材质组合；现有金蝶物料名称仅供对照，不会被自动修改。"));
   Table(preview.Lines.Select(OrderMap).ToList(),row=>OrderLineDetail(preview.Lines.Single(l=>l.Input.Id==row["__id"]),ctx));
  }
  static Dictionary<string,string> OrderMap(ResolvedLine l){return new Dictionary<string,string>{{"导出单号",l.BillNo},{"客户",l.Input.Customer},{"客户PO",l.Input.Po},{"图纸",l.Input.Drawing},{"款号",l.Input.Model},{"色号",l.Input.Color},{"成品类别",l.Category},{"镜架材质",l.Frame},{"镜片描述",l.Input.Lens},{"中间段",l.Middle},{"商品编码",l.Code},{"组合商品名称",l.Name},{"金蝶原名称",l.OriginalName},{"物料状态",l.IsNew?"待新建":"现有/待核查"},{"商品类别编码",l.ProductClass},{"数量",PriceParser.Num(l.Qty)},{"单位",l.Unit},{"原币种",l.Currency},{"原币单价",l.SourcePrice},{"人民币单价",l.Price.ToString("0.0000",System.Globalization.CultureInfo.InvariantCulture)},{"人民币金额",l.Amount.ToString("0.00",System.Globalization.CultureInfo.InvariantCulture)},{"赠品",l.Input.Gift},{"核对状态",l.Errors.Count==0?"可确认":string.Join("；",l.Errors)},{"价格依据",l.PriceEvidence},{"物料依据",l.MaterialEvidence},{"人工依据",l.Input.Note},{"来源表",l.Input.Source.Sheet},{"来源行",l.Input.Source.Row.ToString()},{"__id",l.Input.Id}};}
  void UploadOrder(){string file=Pick("选择订单原件");if(file==null)return;var parsed=PriceParser.Parse(file);if(parsed.Rows.Count==0)throw new InvalidDataException("未识别到订单明细，请核对 Drawing / Model / Colourway 等表头映射。");var chosen=new List<string>();
   var win=new Window{Title="选择本次订单工作表",Owner=this,Width=670,Height=560,WindowStartupLocation=WindowStartupLocation.CenterOwner};var dock=new DockPanel{Margin=new Thickness(20)};var panel=new StackPanel();var checks=new List<CheckBox>();panel.Children.Add(Label("同一订单不同版本请只选一张。未勾选的工作表不会进入草稿。"));var groups=parsed.Rows.GroupBy(p=>p.Sheet).ToList();foreach(var g in groups){var cb=new CheckBox{Content=g.Key+" · "+g.Count()+" 行 · "+string.Join("、",g.Select(p=>p.Pi).Distinct()),Tag=g.Key,IsChecked=groups.Count==1,Margin=new Thickness(0,8,0,8)};checks.Add(cb);panel.Children.Add(cb);}panel.Children.Add(Label(string.Join("\n",parsed.Skipped)));
   var buttons=new WrapPanel();DockPanel.SetDock(buttons,Dock.Bottom);dock.Children.Add(buttons);buttons.Children.Add(Btn("建立草稿",()=>{chosen=checks.Where(c=>c.IsChecked==true).Select(c=>(string)c.Tag).ToList();if(chosen.Count==0)throw new InvalidOperationException("请至少选择一张明细表。");win.DialogResult=true;}));var cancel=Btn("取消",()=>win.Close());cancel.IsCancel=true;buttons.Children.Add(cancel);dock.Children.Add(new ScrollViewer{Content=panel,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});win.Content=dock;if(win.ShowDialog()!=true)return;
   var draft=OrderFlow.Create(parsed,chosen,store.CodingRules());store.ArchiveOrder(parsed);store.SaveDraft(draft);currentDraft=draft;Orders();
  }
  void InvalidateAndSave(){currentDraft.ReviewHash="";currentDraft.ReviewedAt="";currentDraft.ReviewedBy="";store.SaveDraft(currentDraft);Orders();}
  void DraftLibrary(){Heading("已保存订单草稿","打开查看不会保存或更改草稿；每次编辑保留独立版本。");var drafts=store.Drafts();content.Children.Add(Btn("返回订单",Orders));Table(drafts.Select(d=>new Dictionary<string,string>{{"文件",d.File},{"版本",d.Version.ToString()},{"行数",d.Lines.Count.ToString()},{"已确认时间",d.ReviewedAt},{"原件哈希",d.SourceHash},{"__id",d.Id}}).ToList(),r=>{currentDraft=drafts.Single(d=>d.Id==r["__id"]);Orders();});}
  void ExportLibrary(){Heading("金蝶导出记录","记录文件哈希与核对指纹；导出成功不代表金蝶导入成功。");content.Children.Add(Btn("返回订单",Orders));Table(store.ExportHistory(),r=>Detail("导出详情",string.Join("\n\n",r.Select(p=>p.Key+"："+p.Value)),null));}
  void TemplateSettings(){Heading("金蝶导入模板","使用金蝶导出的原版 .xlsx 模板。模板按哈希保留版本，更新后须重新核对订单。");foreach(string kind in new[]{"sales","material"}){string type=kind;var info=store.CurrentTemplate(type);content.Children.Add(Label((type=="sales"?"销售订单":"商品新建")+"："+(info==null?"未设置":info.File+"\n"+info.Hash+"\n导出副本将修正 "+info.RangeRepairs.Count+" 个空列字典引用；原模板完整保留")));content.Children.Add(Btn("选择"+(type=="sales"?"销售订单":"商品")+"模板",()=>{string path=Pick("选择金蝶原版模板");if(path!=null){store.InstallTemplate(path,type);TemplateSettings();}}));}content.Children.Add(Btn("返回订单",Orders));}
  // Modal editing uses a detached copy. Cancel/close never writes a business draft.
  bool EditFields(string title,object target,IEnumerable<string[]> fields,Dictionary<string,List<string>> options){var win=new Window{Title=title,Owner=this,Width=720,Height=690,WindowStartupLocation=WindowStartupLocation.CenterOwner};var dock=new DockPanel{Margin=new Thickness(22)};var form=new StackPanel();var readers=new Dictionary<string,Func<string>>();foreach(var pair in fields){string key=pair[0];form.Children.Add(Label(pair[1]));string value=(string)target.GetType().GetField(key).GetValue(target);List<string> values;if(options.TryGetValue(key,out values)){var cb=new ComboBox{IsEditable=true,ItemsSource=values,Text=value,MinHeight=30};form.Children.Add(cb);readers[key]=()=>cb.Text.Trim();}else{var box=new TextBox{Text=value,MinHeight=30,TextWrapping=TextWrapping.Wrap,AcceptsReturn=key=="Note",MaxHeight=140};form.Children.Add(box);readers[key]=()=>box.Text.Trim();}}
   var buttons=new WrapPanel();DockPanel.SetDock(buttons,Dock.Bottom);dock.Children.Add(buttons);buttons.Children.Add(Btn("保存草稿修改",()=>{foreach(var r in readers)target.GetType().GetField(r.Key).SetValue(target,r.Value());win.DialogResult=true;}));var cancel=Btn("取消",()=>win.Close());cancel.IsCancel=true;buttons.Children.Add(cancel);dock.Children.Add(new ScrollViewer{Content=form,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});win.Content=dock;return win.ShowDialog()==true;}
  void EditOrderSettings(OrderContext ctx){var copy=PriceParser.Json.Deserialize<OrderSettings>(PriceParser.Json.Serialize(currentDraft.Settings));var options=new Dictionary<string,List<string>>{{"BusinessType",new List<string>{"赊销","现销"}}};if(ctx.SalesTemplate!=null){options["Salesperson"]=ctx.SalesTemplate.Options("empid.name");options["PcsUnit"]=ctx.SalesTemplate.Options("unit.name");}if(ctx.MaterialTemplate!=null)options["Warehouse"]=ctx.MaterialTemplate.Options("stockid.name");if(EditFields("导出参数",copy,new[]{new[]{"BillDate","单据日期 yyyy-MM-dd"},new[]{"DeliveryDate","预计交货日期 yyyy-MM-dd"},new[]{"Salesperson","业务员（按模板字典）"},new[]{"BusinessType","业务类型"},new[]{"Rate","美元转人民币汇率"},new[]{"Factor","美元折算系数"},new[]{"Tax","税率 %"},new[]{"PcsUnit","来源 PCS 对应金蝶单位（数量不变）"},new[]{"Warehouse","新建商品默认仓库"}},options)){currentDraft.Settings=copy;InvalidateAndSave();}}
  void OrderLineDetail(ResolvedLine line,OrderContext ctx){string detail=string.Join("\n\n",OrderMap(line).Where(p=>!p.Key.StartsWith("__")).Select(p=>p.Key+"："+p.Value))+"\n\n原单完整识别依据\n"+string.Join("\n",PriceMap(line.Input.Source).Select(p=>p.Key+"："+p.Value))+"\n\n物料候选\n"+string.Join("\n",line.Candidates.Select(m=>m.Code+" | "+m.Values["物料名称"]+" | "+m.Values["基本单位"]+" | "+m.File+" / "+m.Sheet+":"+m.Row))+"\n\n价格候选\n"+string.Join("\n",line.PriceCandidates.Select(p=>p.Currency+" "+p.UnitPrice+" | "+p.Status+" | "+p.File+" / "+p.Sheet+":"+p.Row+"\n"+p.Evidence));
   Detail("订单行 · "+line.Input.Drawing,detail,()=>{var save=new SaveFileDialog{Filter="Excel (*.xlsx)|*.xlsx",FileName=Path.GetFileNameWithoutExtension(line.Input.Source.File)+"-原件副本.xlsx"};if(save.ShowDialog()==true)store.CopyOriginal(line.Input.Source,save.FileName);},()=>EditOrderLine(line,ctx),"修改本行草稿");}
  void EditOrderLine(ResolvedLine line,OrderContext ctx){var copy=PriceParser.Json.Deserialize<OrderLine>(PriceParser.Json.Serialize(line.Input));var opts=new Dictionary<string,List<string>>{{"Category",ctx.Rules.Select(r=>r.Category).ToList()},{"Frame",ctx.Names.Select(n=>n.Code).ToList()},{"Lens",ctx.Lenses.Select(n=>n.Keyword).Distinct().ToList()},{"ChosenCode",line.Candidates.Select(m=>m.Code).Distinct().ToList()},{"ManualCurrency",new List<string>{"USD","CNY"}},{"Gift",new List<string>{"否","是"}}};if(ctx.MaterialTemplate!=null)opts["ProductClass"]=ctx.MaterialTemplate.Options("parent.number");if(ctx.SalesTemplate!=null){opts["Customer"]=ctx.SalesTemplate.Options("customerid.number");opts["Unit"]=ctx.SalesTemplate.Options("unit.name");}
   if(EditFields("修改订单行（有人工单价时必须填写依据）",copy,new[]{new[]{"BillNo","单据编号"},new[]{"Po","客户订单号"},new[]{"Customer","客户编号"},new[]{"Drawing","图纸号"},new[]{"Model","客款号"},new[]{"Color","色号"},new[]{"Category","成品类别"},new[]{"Frame","镜架材质（用于商品名称）"},new[]{"Lens","镜片描述：白片 / 强化白片 / 太阳 / sun"},new[]{"Board","板料编码（按所选成品规则使用）"},new[]{"Plating","电镀色（按所选成品规则使用）"},new[]{"ChosenCode","指定现有物料编码（留空自动匹配）"},new[]{"Quantity","数量"},new[]{"Unit","金蝶单位（留空按清单及参数匹配）"},new[]{"ProductClass","新建商品类别编码（留空尝试使用成品类别）"},new[]{"ManualPrice","人工核定原币单价（留空恢复自动匹配）"},new[]{"ManualCurrency","人工单价币种"},new[]{"Gift","是否赠品"},new[]{"Note","人工核对依据 / 备注"}},opts)){copy.UseManualPrice=copy.ManualPrice!="";int index=currentDraft.Lines.IndexOf(line.Input);currentDraft.Lines[index]=copy;InvalidateAndSave();}}
 }
}
